using System.Drawing.Drawing2D;
using System.Runtime.InteropServices;

namespace ImmichBg.UI;

/// <summary>App logo images (embedded resources, generated by tools/make-icons.ps1).</summary>
internal static class AppImages
{
    /// <summary>Window/taskbar icon (all sizes).</summary>
    public static readonly Icon AppIcon = new(Resource("app.ico"));

    /// <summary>Full logo, for big sizes.</summary>
    public static readonly Bitmap Logo = new(Resource("logo.png"));

    /// <summary>The flower only: stays readable at 16-48 px.</summary>
    public static readonly Bitmap LogoSmall = new(Resource("logo-small.png"));

    static Stream Resource(string name) =>
        typeof(AppImages).Assembly.GetManifestResourceStream(name) ?? throw new InvalidOperationException(name);
}

/// <summary>Tray icons: the logo with a small coloured status dot (no dot when everything is fine).</summary>
internal static class TrayIcons
{
    public static readonly Icon Ok = Make(null);
    public static readonly Icon Idle = Make(Color.FromArgb(150, 152, 162));
    public static readonly Icon Syncing = Make(Color.FromArgb(37, 140, 235));
    public static readonly Icon Error = Make(Theme.Danger);

    public static Icon For(SyncState state) => state switch
    {
        SyncState.Ok => Ok,
        SyncState.Syncing => Syncing,
        SyncState.Error => Error,
        _ => Idle,
    };

    static Icon Make(Color? badge)
    {
        const int size = 32;
        using var bmp = new Bitmap(size, size);
        using (var g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.InterpolationMode = InterpolationMode.HighQualityBicubic;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.DrawImage(AppImages.LogoSmall, 0, 0, size, size);
            if (badge is { } color)
            {
                // White ring so the dot stands out on any taskbar colour.
                using var ring = new SolidBrush(Color.White);
                g.FillEllipse(ring, 17, 17, 15, 15);
                using var dot = new SolidBrush(color);
                g.FillEllipse(dot, 19, 19, 11, 11);
            }
        }
        var handle = bmp.GetHicon();
        try
        {
            using var temp = Icon.FromHandle(handle);
            return (Icon)temp.Clone();
        }
        finally
        {
            DestroyIcon(handle);
        }
    }

    [DllImport("user32.dll")]
    static extern bool DestroyIcon(IntPtr handle);
}
